example.code:
{
  "currency": "EUR",
  "tiers": [
    {
      "name": "good", "price": 3000,
      "delivery_cost": {"hours": 20, "loaded_hourly_cost": 90, "pass_through": 200},
      "gross_margin_abs": 1000, "gross_margin_pct": 0.333,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 2, "turnaround_days": 5},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 3}
      ]
    },
    {
      "name": "better", "price": 5000,
      "delivery_cost": {"hours": 28, "loaded_hourly_cost": 90, "pass_through": 300},
      "gross_margin_abs": 2180, "gross_margin_pct": 0.436,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 4, "turnaround_days": 3},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 2},
        {"name": "conversion tracking setup", "quantity": 1, "turnaround_days": 10},
        {"name": "weekly optimisation call", "quantity": 4, "turnaround_days": 7}
      ]
    },
    {
      "name": "best", "price": 8000,
      "delivery_cost": {"hours": 36, "loaded_hourly_cost": 90, "pass_through": 400},
      "gross_margin_abs": 4360, "gross_margin_pct": 0.545,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 8, "turnaround_days": 2},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 1},
        {"name": "conversion tracking setup", "quantity": 1, "turnaround_days": 5},
        {"name": "weekly optimisation call", "quantity": 4, "turnaround_days": 7},
        {"name": "landing page A/B test", "quantity": 2, "turnaround_days": 14}
      ]
    }
  ],
  "fence": {"omitted_deliverable": "conversion tracking setup", "needed_for": "an e-commerce ICP cannot report ROAS without conversion tracking", "named_on_rate_sheet": true},
  "default_recommendation": "better",
  "presentation": {"order": ["best", "better", "good"], "prices_visible": true},
  "scope_up": {
    "trigger": "client requests a deliverable or quantity outside the current tier's list",
    "price_rule": "difference between the two tier prices pro-rated to the remaining term",
    "approver": "account director",
    "written_confirmation_required": true,
    "free_goodwill_allowed": false
  },
  "concessions": {"method": "remove_named_deliverable_or_quantity", "published_prices_vary_by_client": false},
  "steps": [
    {"id": "s1", "name": "cost every tier", "exit_criterion": "best gross margin is the highest in EUR and percent: 4360 / 54.5 percent against 2180 / 43.6 and 1000 / 33.3", "output_location": "pricing/2026-05-rate-sheet.md"},
    {"id": "s2", "name": "publish best-first rate sheet", "exit_criterion": "rate sheet lists best, better, good with prices visible and the fence named under good", "output_location": "pricing/2026-05-rate-sheet.md"},
    {"id": "s3", "name": "brief account managers on scope-up", "exit_criterion": "every account manager can state trigger, price rule and approver; first scope-up logged with written confirmation", "output_location": "pricing/scope-up-log.md"}
  ]
}

{
  "currency": "EUR",
  "tiers": [
    {
      "name": "good", "price": 5000,
      "delivery_cost": {"hours": 30, "loaded_hourly_cost": 90, "pass_through": 200},
      "gross_margin_abs": 2100, "gross_margin_pct": 0.42,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 2, "turnaround_days": 5},
        {"name": "conversion tracking setup", "quantity": 1, "turnaround_days": 10},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 3}
      ]
    },
    {
      "name": "better", "price": 10000,
      "delivery_cost": {"hours": 70, "loaded_hourly_cost": 90, "pass_through": 300},
      "gross_margin_abs": 3400, "gross_margin_pct": 0.34,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 4, "turnaround_days": 3},
        {"name": "social campaigns managed", "quantity": 2, "turnaround_days": 3},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 2}
      ]
    },
    {
      "name": "best", "price": 15000,
      "delivery_cost": {"hours": 140, "loaded_hourly_cost": 90, "pass_through": 400},
      "gross_margin_abs": 2000, "gross_margin_pct": 0.133,
      "deliverables": [
        {"name": "paid search campaigns managed", "quantity": 8, "turnaround_days": 2},
        {"name": "monthly performance report", "quantity": 1, "turnaround_days": 1},
        {"name": "landing page A/B test", "quantity": 4, "turnaround_days": 14},
        {"name": "creative production", "quantity": 6, "turnaround_days": 10}
      ]
    }
  ],
  "fence": {"omitted_deliverable": "conversion tracking setup", "needed_for": "an e-commerce ICP cannot report ROAS without conversion tracking", "named_on_rate_sheet": true},
  "default_recommendation": "better",
  "presentation": {"order": ["good", "better", "best"], "prices_visible": false},
  "scope_up": {
    "trigger": "client asks for something extra",
    "price_rule": "difference between the two tier prices pro-rated to the remaining term",
    "approver": "account manager",
    "written_confirmation_required": true,
    "free_goodwill_allowed": true
  },
  "concessions": {"method": "remove_named_deliverable_or_quantity", "published_prices_vary_by_client": true},
  "steps": [
    {"id": "s1", "name": "publish rate sheet", "exit_criterion": "shipped", "output_location": "pricing/rate-sheet.md"}
  ]
}
